# Generated by build.py from recipe.yml for recipe mqtt-subscribe-with-a-wildcard. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', '--topic', '"sensors/#;retain"', 'mqtt://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
curl.exe -s -d 21 mqtt://127.0.0.1:8080/sensors/kitchen/temp
curl.exe -s -d 19 mqtt://127.0.0.1:8080/sensors/hall/temp
curl.exe -s -d 40 mqtt://127.0.0.1:8080/sensors/kitchen/humidity
curl.exe -s -d 180 mqtt://127.0.0.1:8080/sensors/kitchen/oven/temp
curl.exe -s -d 5 mqtt://127.0.0.1:8080/sensors/temp
curl.exe -s -d up mqtt://127.0.0.1:8080/sensors
try { curl.exe -s mqtt://127.0.0.1:8080/sensors/+/temp } finally { Stop-Process $server0 }
